import java.util.HashSet;

public class CommonElements {

    public static void main(String[] args) {

        int[] a = {4, 9, 5, 1, 7};
        int[] b = {9, 4, 9, 8, 4};

        // ধাপ ১ — b-এর সব মান একবারে Set-এ তুলে রাখি
        HashSet<Integer> inB = new HashSet<>();
        for (int j = 0; j < b.length; j++) {
            inB.add(b[j]);
        }

        // ধাপ ২ — a-এর যেসব মান b-তেও আছে, সেগুলো এখানে জমে
        // Set একই মান দুবার রাখে না, তাই duplicate নিয়ে ভাবতে হয় না
        HashSet<Integer> common = new HashSet<>();

        for (int i = 0; i < a.length; i++) {
            if (inB.contains(a[i])) {
                common.add(a[i]);
            }
        }

        System.out.println("Common: " + common);
    }
}

/*  Output:
    Common: [4, 9]                                 */

