public class SecondLargest {

    public static void main(String[] args) {

        int[] arr = {12, 35, 1, 10, 35, 2};

        // ধাপ ১ — সবচেয়ে বড়টি বের করি
        int largest = arr[0];
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] > largest) {
                largest = arr[i];
            }
        }

        // ধাপ ২ — largest বাদ দিয়ে আবার সবচেয়ে বড়টি
        int second = -1;
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] > second && arr[i] != largest) {
                second = arr[i];
            }
        }

        System.out.println("Largest : " + largest);
        System.out.println("Second  : " + second);
    }
}

/*  Output:
    Largest : 35
    Second  : 12                                   */

import java.util.HashMap;

public class RemoveDuplicates {

    public static void main(String[] args) {

        int[] arr = {5, 3, 5, 8, 3, 9, 8};

        // মান → সেটি এ পর্যন্ত কতবার এসেছে
        HashMap<Integer, Integer> count = new HashMap<>();

        System.out.print("Unique: ");

        for (int i = 0; i < arr.length; i++) {

            // আগে না থাকলে 0 ধরে নিয়ে 1 যোগ
            int c = count.getOrDefault(arr[i], 0) + 1;
            count.put(arr[i], c);

            // c == 1 মানে এই মানটি এবারই প্রথম এলো
            if (c == 1) {
                System.out.print(arr[i] + " ");
            }
        }
    }
}

/*  Output:
    Unique: 5 3 8 9                                */

public class MissingNumber {

    public static void main(String[] args) {

        // 1 থেকে 8 এর মধ্যে একটি সংখ্যা নেই
        int[] arr = {1, 2, 4, 5, 6, 7, 8};
        int n = arr.length + 1;

        // 1 থেকে n পর্যন্ত যোগফল কত হওয়ার কথা ছিল
        int total = n * (n + 1) / 2;

        // array-তে আসলে যোগফল কত আছে
        int sum = 0;
        for (int i = 0; i < arr.length; i++) {
            sum = sum + arr[i];
        }

        System.out.println("Total (1..n) : " + total);
        System.out.println("Array sum    : " + sum);
        System.out.println("Missing      : " + (total - sum));
    }
}

/*  Output:
    Total (1..n) : 36
    Array sum    : 33
    Missing      : 3                               */

public class LeftRotate {

    public static void main(String[] args) {

        int[] arr = {1, 2, 3, 4, 5, 6};
        int k = 2;                  // কত ঘর বাঁয়ে সরবে

        int n = arr.length;
        int[] out = new int[n];

        for (int i = 0; i < n; i++) {
            out[i] = arr[(i + k) % n];
        }

        System.out.print("Rotated: ");
        for (int i = 0; i < n; i++) {
            System.out.print(out[i] + " ");
        }
    }
}

/*  Output:
    Rotated: 3 4 5 6 1 2                           */

public class PairWithSum {

    public static void main(String[] args) {

        int[] arr = {2, 7, 11, 15, 4, 6};
        int target = 13;

        System.out.println("Target = " + target);

        for (int i = 0; i < arr.length; i++) {
            for (int j = i + 1; j < arr.length; j++) {

                if (arr[i] + arr[j] == target) {
                    System.out.println(arr[i] + " + " + arr[j]);
                }
            }
        }
    }
}

/*  Output:
    Target = 13
    2 + 11
    7 + 6                                          */
